<template><view class="p"><text class="t">语法学习</text><text class="s">选择阶段进入专项练习</text><view v-for="x in stages" :key="x.id" class="card" @click="go(x.id)"><text class="n">{{x.id}}</text><view><text class="name">{{x.name}}</text><text class="desc">{{x.desc}}</text></view><text>›</text></view></view></template><script>export default{data(){return{wrongCount:0,stages:[{id:1,name:'基础句型',desc:'词类、句子成分、基础句型与常用时态'},{id:2,name:'核心语法',desc:'时态、词类、情态动词、主谓一致与被动语态'},{id:3,name:'进阶语法',desc:'各类从句、非谓语、虚拟语气与高级句式'}]}},onShow(){this.wrongCount=(uni.getStorageSync('grammar_wrong')||[]).length},methods:{go(id){uni.navigateTo({url:'/pages/grammar/list?stage='+id})}}}</script><style>.p{min-height:100vh;padding:30rpx;background:#f7f5f0}.t,.name{display:block;font-weight:bold;color:#1f3a5f}.t{font-size:44rpx}.s,.desc{display:block;color:#888;margin:10rpx 0 25rpx}.card,.wrong{display:flex;align-items:center;gap:20rpx;background:#fff;padding:30rpx;border-radius:18rpx;margin:18rpx 0}.n{background:#1f3a5f;color:#fff;padding:12rpx 20rpx;border-radius:50%}.card view{flex:1}.name{font-size:32rpx}.wrong{color:#ef4444;font-weight:bold}</style>
